SELECT jsonb_build_object('triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'function_name',p.proname,'body',pg_get_functiondef(p.oid))) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='zoi.listings'::regclass AND NOT t.tgisinternal),'publication_functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'body',pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='zoi' AND p.prokind='f' AND (p.proname ILIKE '%publish%' OR p.proname ILIKE '%maint%'))) AS publication_review;
